"""Render the data dictionary from SQLAlchemy metadata (single source of truth)."""

from __future__ import annotations

from observatory.db.models import Base


def render_data_dictionary() -> str:
    lines = [
        "# Data dictionary",
        "",
        "> Generated by `python -m observatory.cli data-dictionary` from `src/observatory/db/models.py`.",
        "> Do not edit by hand; `tests/test_schema.py` fails if this file is stale.",
        "",
    ]
    for table in sorted(Base.metadata.sorted_tables, key=lambda t: t.name):
        lines += [f"## `{table.name}`", ""]
        if table.comment:
            lines += [table.comment, ""]
        lines += ["| Column | Type | Null | Key | Description |", "|---|---|---|---|---|"]
        for col in table.columns:
            key = "PK" if col.primary_key else ", ".join(f"FK→{fk.column.table.name}" for fk in col.foreign_keys)
            ctype = "vector" if col.type.__class__.__name__ == "VectorType" else str(col.type)
            desc = (col.comment or "").replace("|", "\\|")
            lines.append(f"| `{col.name}` | {ctype} | {'yes' if col.nullable else 'no'} | {key} | {desc} |")
        lines.append("")
    return "\n".join(lines)


def render_mermaid_er() -> str:
    """ER diagram of the core analytical chain, generated from metadata."""
    core = [
        "source_dataset",
        "source_version",
        "occupation",
        "occupation_task",
        "task",
        "occupation_source_mapping",
        "ai_capability_version",
        "ai_capability",
        "semantic_mapping",
        "embedding",
        "exposure_assessment",
        "exposure_component",
        "ai_evidence",
    ]
    tables = {t.name: t for t in Base.metadata.sorted_tables}
    out = ["erDiagram"]
    for name in core:
        t = tables[name]
        for col in t.columns:
            for fk in col.foreign_keys:
                target = fk.column.table.name
                if target in core:
                    out.append(f'    {target} ||--o{{ {name} : "{col.name}"')
    return "\n".join(dict.fromkeys(out))
